export const allTools: Tool[] = Array.from(new Set([
    ...popularTools,
    ...imageToVideoTools,
    ...textToVideoTools,
    ...textToSpeechTools,
    ...voiceCloningTools,
    ...aiAvatarTools,
    ...textToImageTools,
    ...businessToolData.flatMap(cat => cat.tools),
    ...graphicDesignToolData.flatMap(cat => cat.tools)
].map(t => t.name))).map(name => {
    return [
        ...popularTools,
        ...imageToVideoTools,
        ...textToVideoTools,
        ...textToSpeechTools,
        ...voiceCloningTools,
        ...aiAvatarTools,
        ...textToImageTools,
        ...businessToolData.flatMap(cat => cat.tools),
        ...graphicDesignToolData.flatMap(cat => cat.tools)
    ].find(t => t.name === name)!
});

